bool storage_isPinCorrect_impl(const char *pin, const uint8_t wrapped_key[64], const uint8_t fingerprint[32], uint8_t key[64]) { /* <=== storage_isPinCorrect_impl */ 
    uint8_t wrapping_key[64];
    storage_deriveWrappingKey(pin, wrapping_key);
    storage_unwrapStorageKey(wrapping_key, wrapped_key, key);

    uint8_t fp[32];
    storage_keyFingerprint(key, fp);

    bool ret = memcmp(fp, fingerprint, 32) == 0;
    if (!ret)
        memzero(key, 64);
    memzero(wrapping_key, 64);
    memzero(fp, 32);
    return ret;
}

void fsm_sendSuccess(const char *text) /* <=== fsm_sendSuccess */ 
{
    if(reset_msg_stack)
    {
        fsm_msgInitialize((Initialize *)0);
        reset_msg_stack = false;
        return;
    }

    RESP_INIT(Success);

    if(text)
    {
        resp->has_message = true;
        strlcpy(resp->message, text, sizeof(resp->message));
    }

    msg_write(MessageType_MessageType_Success, resp);
}

