bool exact_str_match(const char *str1, const char *str2, uint32_t len) /* <=== exact_str_match */ 
{
    volatile uint32_t match = 0;

    // Access through volatile ptrs to prevent compiler optimizations that
    // might leak timing information.
    const char volatile * volatile str1_v = str1;
    const char volatile * volatile str2_v = str2;

    for(uint32_t i = 0; i < len && i < CURRENT_WORD_BUF; i++)
    {
        if(str1_v[i] == str2_v[i])
        {
            match++;
        } else {
            match--;
        }
    }

    return match == len;
}

static void run_pin_state(PINState *pin_state, PINInfo *pin_info) /* <=== run_pin_state */ 
{
    switch(*pin_state)
    {

        /* Send PIN request */
        case PIN_REQUEST:
            if(pin_info->type)
            {
                send_pin_request(pin_info->type);
            }

            pin_info->pin_ack_msg = PIN_ACK_WAITING;
            *pin_state = PIN_WAITING;
            break;

        /* Wait for a PIN */
        case PIN_WAITING:
            check_for_pin_ack(pin_info);

            if(pin_info->pin_ack_msg != PIN_ACK_WAITING)
            {
                *pin_state = PIN_FINISHED;
            }

            break;

        case PIN_FINISHED:
        case PIN_ACK:
        default:
            break;
    }
}

