}

static void decode_pin(PINInfo *pin_info) /* <=== decode_pin */ 
{
    for(uint32_t i = 0; i < strlen(pin_info->pin); i++)
    {
        int32_t j = pin_info->pin[i] - '1';

        if(j >= 0 && (uint32_t)j < strlen(pin_matrix))
        {
            pin_info->pin[i] = pin_matrix[j];
        }
        else
        {
            pin_info->pin[i] = 'X';
        }
    }
}

