bool storage_isPinCorrect(const char *pin) { /* <=== storage_isPinCorrect */ 
    uint8_t storage_key[64];
    bool ret = storage_isPinCorrect_impl(pin,
                                         shadow_config.storage.pub.wrapped_storage_key,
                                         shadow_config.storage.pub.storage_key_fingerprint,
                                         storage_key);
    memzero(storage_key, 64);
    return ret;
}

void session_clear_impl(SessionState *ss, Storage *storage, bool clear_pin) /* <=== session_clear_impl */ 
{
    ss->seedCached = false;
    memset(&ss->seed, 0, sizeof(ss->seed));

    ss->passphraseCached = false;
    memset(&ss->passphrase, 0, sizeof(ss->passphrase));

    if (!storage_hasPin_impl(storage)) {
        ss->pinCached =
            storage_isPinCorrect_impl("",
                                      storage->pub.wrapped_storage_key,
                                      storage->pub.storage_key_fingerprint,
                                      ss->storageKey);

        if (!ss->pinCached)
            goto clear;

        storage_secMigrate(ss, storage, /*encrypt=*/false);
        return;
    }

    if (!clear_pin) {
        return;
    }

clear:
    memzero(ss->storageKey, sizeof(ss->storageKey));
    ss->pinCached = false;
    storage->has_sec = false;
    memzero(&storage->sec, sizeof(storage->sec));
}

bool change_pin(void) /* <=== change_pin */ 
{
    PINInfo pin_info_first, pin_info_second;

    /* Set request types */
    pin_info_first.type =   PinMatrixRequestType_PinMatrixRequestType_NewFirst;
    pin_info_second.type =  PinMatrixRequestType_PinMatrixRequestType_NewSecond;

    if (!pin_request("Enter New PIN", &pin_info_first)) {
        return false;
    }

    if (!pin_request("Re-Enter New PIN", &pin_info_second)) {
        return false;
    }

    if (strcmp(pin_info_first.pin, pin_info_second.pin) != 0) {
        return false;
    }

    storage_setPin(pin_info_first.pin);
    return true;
}

bool pin_protect(const char *prompt) /* <=== pin_protect */ 
{
    if (!storage_hasPin()) {
        return true;
    }

    // Check for prior PIN failed attempts and apply exponentially longer delay
    // for each subsequent failed attempt.
    uint32_t fail_count = storage_getPinFails();
    if (fail_count > 2) {
        uint32_t wait = (fail_count < 32)
            ? (1u << fail_count)
            : 0xFFFFFFFFu;

        // snprintf: 36 + 10 (%u) + 1 (NULL) = 47
        memzero(warn_msg_fmt, sizeof(warn_msg_fmt));
        snprintf(warn_msg_fmt, sizeof(warn_msg_fmt),
                 "Previous PIN Failures:\nWait %" PRIu32 " seconds",
                 wait);
        layout_warning(warn_msg_fmt);

        remaining_wait = total_wait = wait;

        while (--remaining_wait > 0) {
            delay_ms_with_callback(ONE_SEC, &pin_fail_wait_handler, 20);
        }
    }

    // Set request type
    PINInfo pin_info;
    pin_info.type = PinMatrixRequestType_PinMatrixRequestType_Current;

    // Get PIN
    if (!pin_request(prompt, &pin_info)) {
        // PIN entry has been canceled by the user
        return false;
    }

    // Preincrement the failed counter before authentication
    storage_increasePinFails();
    bool pre_increment_cnt_flg = (fail_count >= storage_getPinFails());

    // Authenticate user PIN
    if (!storage_isPinCorrect(pin_info.pin) || pre_increment_cnt_flg) {
        fsm_sendFailure(FailureType_Failure_PinInvalid, "Invalid PIN");
        return false;
    }

    session_cachePin(pin_info.pin);
    storage_resetPinFails();
    return true;
}

static uint32_t get_current_word_pos(void) /* <=== get_current_word_pos */ 
{
    char *pos_num = strchr(mnemonic, ' ');
    uint32_t word_pos = 0;

    while(pos_num != NULL)
    {
        word_pos++;
        pos_num = strchr(++pos_num, ' ');
    }

    return word_pos;
}

