static void wear_leveling_shift(void) /* <=== wear_leveling_shift */ 
{
    switch(storage_location)
    {
        case FLASH_STORAGE1:
        {
            storage_location = FLASH_STORAGE2;
            break;
        }

        case FLASH_STORAGE2:
        {
            storage_location = FLASH_STORAGE3;
            break;
        }

        /* wraps around */
        case FLASH_STORAGE3:
        {
            storage_location = FLASH_STORAGE1;
            break;
        }

        default:
        {
            storage_location = STORAGE_SECT_DEFAULT;
            break;
        }
    }
}

static void format_current_word(char *current_word, bool auto_completed) /* <=== format_current_word */ 
{
    static char CONFIDENTIAL temp_word[CURRENT_WORD_BUF];
    uint32_t word_num = get_current_word_pos() + 1;

    snprintf(temp_word, CURRENT_WORD_BUF, "%" PRIu32 ".%s", word_num, current_word);

    /* Pad with dashes */
    size_t pos_len = strlen(current_word);
    if (pos_len < 4)
    {
        for (size_t i = 0; i < 4 - pos_len; i++)
        {
            strlcat(temp_word, "-", CURRENT_WORD_BUF);
        }
    }

    /* Mark as auto completed */
    if(auto_completed)
    {
        temp_word[strlen(temp_word) + 1] = '\0';
        temp_word[strlen(temp_word)] = '~';
    }

    strlcpy(current_word, temp_word, CURRENT_WORD_BUF);
    memzero(temp_word, sizeof(temp_word));
}

bool msg_write(MessageType msg_id, const void *msg) /* <=== msg_write */ 
{
	const pb_field_t *fields = message_fields(NORMAL_MSG, msg_id, OUT_MSG);

	if (!fields)
		return false;

	TrezorFrameBuffer framebuf;
	memset(&framebuf, 0, sizeof(framebuf));
	framebuf.frame.usb_header.hid_type = '?';
	framebuf.frame.header.pre1 = '#';
	framebuf.frame.header.pre2 = '#';
	framebuf.frame.header.id = __builtin_bswap16(msg_id);

	pb_ostream_t os = pb_ostream_from_buffer(framebuf.buffer, sizeof(framebuf.buffer));

	if (!pb_encode(&os, fields, msg))
		return false;

	framebuf.frame.header.len = __builtin_bswap32(os.bytes_written);

	// Chunk out data
	for (uint32_t pos = 1; pos < sizeof(framebuf.frame) + os.bytes_written; pos += 64 - 1) {
		uint8_t tmp_buffer[64] = { 0 };

		tmp_buffer[0] = '?';

		memcpy(tmp_buffer + 1, ((const uint8_t*)&framebuf) + pos, 64 - 1);

#ifndef EMULATOR
		while (usbd_ep_write_packet(usbd_dev, ENDPOINT_ADDRESS_IN, tmp_buffer, 64) == 0) {};
#else
		emulatorSocketWrite(0, tmp_buffer, sizeof(tmp_buffer));
#endif
	}

	return true;
}

